// Nó Code "Buscar placares" do workflow "Como foram os jogos" (modo: Run Once for All Items)
// Busca o resultado dos jogos que entraram na pauta do dia anterior (tabela Jogos do Airtable).
// - football-data: o placar oficial dos jogos "fd-<id>", numa chamada só, pelos ids.
// - ESPN: para todos os jogos, porque o placar dela traz o "como foi": minuto e autor dos gols, expulsões,
//   posse de bola, placar por quarto e destaques da NBA/NFL. A ESPN não aceita intervalo de datas, então é
//   uma chamada por liga e por dia (o dia é o dos EUA: um jogo da NBA às 0h30 de Brasília ainda é "ontem" lá).
// As respostas da ESPN (40 a 200 KB por liga) são enxugadas aqui, para a execução não guardar o que não usa.
// As chamadas ficam neste Code, e não em nós HTTP, porque as duas fontes nem sempre são usadas: com nós HTTP
// seria preciso IF + Merge, e o Merge trava quando um dos lados não tem item. O token sai das mensagens de erro.

const TZ = 'America/Sao_Paulo';
const token = $env.FOOTBALL_DATA_TOKEN;
const semSegredo = (e) => String(e?.message ?? e).split(token).join('***');
const campos = (item) => ({ id: item.json.id, ...(item.json.fields ?? item.json) });

const { data } = $('Dia da pauta').first().json;

// Caminho de cada campeonato na ESPN (o código é o da tabela Campeonatos)
const CAMINHO_ESPN = {
  BSA: 'soccer/bra.1',
  CLI: 'soccer/conmebol.libertadores',
  CL: 'soccer/uefa.champions',
  PL: 'soccer/eng.1',
  PD: 'soccer/esp.1',
  SA: 'soccer/ita.1',
  BL1: 'soccer/ger.1',
  FL1: 'soccer/fra.1',
  'uefa.europa': 'soccer/uefa.europa',
  nfl: 'football/nfl',
  nba: 'basketball/nba',
};

const campeonatos = new Map($('Campeonatos').all().map(campos).map((c) => [c.id, c]));

// Sem jogo no dia, o Airtable devolve um item vazio (Always Output Data): ele fica de fora aqui
const jogos = $('Jogos da pauta').all().map(campos).filter((j) => j.ID).map((j) => {
  const c = campeonatos.get((j.Campeonato ?? [])[0]) ?? {};
  return {
    id: j.ID,
    campeonato: c.Nome ?? '',
    codigo: c['Código'] ?? '',
    caminhoEspn: CAMINHO_ESPN[c['Código']] ?? null,
    horario: j['Horário'],
    mandante: j.Mandante,
    visitante: j.Visitante,
    nota: j.Nota,
    porQueANota: j['Por que a nota'] ?? '',
    briefing: j.Briefing ?? '',
  };
});

const falhas = [];

// ---------- football-data ----------
const idsFD = jogos.filter((j) => j.id.startsWith('fd-')).map((j) => j.id.slice(3));
let fd = [];
if (idsFD.length) {
  try {
    const r = await this.helpers.httpRequest({
      url: 'https://api.football-data.org/v4/matches',
      qs: { ids: idsFD.join(',') },
      headers: { 'X-Auth-Token': token },
      json: true,
      timeout: 30000,
    });
    fd = (r.matches ?? []).map((m) => ({
      id: `fd-${m.id}`,
      status: m.status,
      nomesMandante: [m.homeTeam.name, m.homeTeam.shortName].filter(Boolean),
      nomesVisitante: [m.awayTeam.name, m.awayTeam.shortName].filter(Boolean),
      final: m.score.fullTime,
      intervalo: m.score.halfTime,
      duracao: m.score.duration,
      penaltis: m.score.penalties ?? null,
    }));
  } catch (e) {
    falhas.push(`football-data: ${semSegredo(e).slice(0, 200)}`);
  }
}

// ---------- ESPN ----------
const lado = (t) => {
  const nota = (t.leaders ?? []).find((l) => l.name === 'rating')?.leaders?.[0];
  return {
    id: String(t.team.id),
    nomes: [t.team.displayName, t.team.shortDisplayName, t.team.name].filter(Boolean),
    homeAway: t.homeAway,
    placar: t.score,
    parciais: (t.linescores ?? []).map((l) => l.value),
    // NBA: "P. Banchero 24 PTS, 7 REB". Na NFL o destaque vem na manchete do jogo.
    destaque: nota ? `${nota.athlete?.shortName ?? nota.athlete?.displayName}: ${nota.displayValue}` : null,
    estatisticas: Object.fromEntries((t.statistics ?? [])
      .filter((s) => ['possessionPct', 'shotsOnTarget', 'totalShots'].includes(s.name))
      .map((s) => [s.name, s.displayValue])),
  };
};
const enxugar = (caminho, ev) => {
  const c = ev.competitions[0];
  return {
    id: String(ev.id),
    caminho,
    utc: ev.date,
    estado: ev.status.type.state, // pre, in, post
    statusNome: ev.status.type.name, // STATUS_FINAL, STATUS_POSTPONED...
    detalhe: ev.status.type.detail, // "Final/OT", "FT", "AET"...
    lados: c.competitors.map(lado),
    lances: (c.details ?? [])
      .filter((d) => d.scoringPlay || d.redCard)
      .map((d) => ({
        minuto: d.clock?.displayValue ?? '',
        gol: !!d.scoringPlay,
        vermelho: !!d.redCard,
        penalti: !!d.penaltyKick,
        contra: !!d.ownGoal,
        jogador: d.athletesInvolved?.[0]?.displayName ?? '',
        timeId: String(d.team?.id ?? ''),
      })),
    manchete: c.headlines?.[0]?.description ?? c.headlines?.[0]?.shortLinkText ?? null,
  };
};

const pedidosESPN = new Set();
for (const j of jogos) {
  if (!j.caminhoEspn || !j.horario) continue;
  const diaEUA = DateTime.fromISO(j.horario).setZone('America/New_York').toFormat('yyyyMMdd');
  pedidosESPN.add(`${j.caminhoEspn}|${diaEUA}`);
}

const espn = [];
for (const pedido of pedidosESPN) {
  const [caminho, dia] = pedido.split('|');
  try {
    const r = await this.helpers.httpRequest({
      url: `https://site.api.espn.com/apis/site/v2/sports/${caminho}/scoreboard`,
      qs: { dates: dia },
      json: true,
      timeout: 30000,
    });
    for (const ev of r.events ?? []) espn.push(enxugar(caminho, ev));
  } catch (e) {
    falhas.push(`ESPN ${caminho} ${dia}: ${semSegredo(e).slice(0, 200)}`);
  }
}

return [{ json: { data, jogos, fd, espn, falhas } }];

// Nó Code "Montar resultados" do workflow "Como foram os jogos" (modo: Run Once for All Items)
// Para cada jogo da pauta, junta o placar e os fatos do jogo: gols com minuto, expulsões, virada,
// gol decisivo no fim, prorrogação, placar por quarto, destaques. Os fatos são calculados aqui, no código,
// e não pelo Gemini: conta de placar e de minuto o modelo pode errar; o código, não.
// Jogos da football-data são achados na ESPN pelo horário (±15 min) e pelo nome dos times, a mesma regra
// usada com a API-Football e a 365Scores. Se não achar, o jogo fica só com o placar da football-data.

const TOLERANCIA = 15 * 60 * 1000;
const { data, jogos, fd, espn, falhas } = $('Buscar placares').first().json;

const campos = (item) => ({ id: item.json.id, ...(item.json.fields ?? item.json) });
const semAcento = (s) => (s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const times = new Map();
for (const t of $('Times').all().map(campos)) {
  for (const nome of (t['Nomes nas APIs'] ?? '').split(',')) {
    if (nome.trim()) times.set(semAcento(nome), t.Nome);
  }
}

const GENERICAS = new Set(['fc', 'cf', 'ac', 'sc', 'afc', 'cd', 'ca', 'ec', 'se', 'rc', 'ssc', 'as', 'club', 'clube', 'de', 'da', 'do', 'the', 'calcio', 'futebol', 'football', 'esporte']);
const palavras = (s) => semAcento(s).replace(/[^a-z0-9]+/g, ' ').split(' ').filter((p) => p.length > 1 && !GENERICAS.has(p));
const parecido = (nomesApi, nomes) => {
  let melhor = 0;
  for (const nomeApi of nomesApi) {
    const canonico = times.get(semAcento(nomeApi));
    if (canonico && nomes.some((n) => times.get(semAcento(n)) === canonico || n === canonico)) return 1;
    const a = palavras(nomeApi);
    for (const n of nomes) {
      const b = palavras(n);
      if (!a.length || !b.length) continue;
      const comuns = a.filter((p) => b.some((q) => p === q || (Math.min(p.length, q.length) >= 3 && (p.startsWith(q) || q.startsWith(p)))));
      melhor = Math.max(melhor, comuns.length / Math.min(a.length, b.length));
    }
  }
  return melhor;
};

// Acha o jogo na ESPN e devolve [mandante, visitante] já na ordem da pauta
const acharNaESPN = (j, nomesMandante, nomesVisitante) => {
  if (j.id.startsWith('espn-')) {
    const ev = espn.find((e) => `espn-${e.id}` === j.id);
    if (!ev) return null;
    return { ev, casa: ev.lados.find((l) => l.homeAway === 'home'), fora: ev.lados.find((l) => l.homeAway === 'away') };
  }
  const inicio = DateTime.fromISO(j.horario).toMillis();
  let melhor = null;
  let pontos = 0;
  for (const ev of espn) {
    if (ev.caminho !== j.caminhoEspn) continue;
    if (Math.abs(DateTime.fromISO(ev.utc).toMillis() - inicio) > TOLERANCIA) continue;
    const [a, b] = ev.lados;
    // Testa também invertido, caso uma fonte troque mandante e visitante
    const direto = parecido(a.nomes, nomesMandante) + parecido(b.nomes, nomesVisitante);
    const invertido = parecido(a.nomes, nomesVisitante) + parecido(b.nomes, nomesMandante);
    if (Math.max(direto, invertido) > pontos) {
      pontos = Math.max(direto, invertido);
      melhor = direto >= invertido ? { ev, casa: a, fora: b } : { ev, casa: b, fora: a };
    }
  }
  // Pelo menos um time inteiro reconhecido (o horário já filtrou quase tudo)
  return pontos >= 1 ? melhor : null;
};

const statusFD = {
  FINISHED: 'Encerrado', AWARDED: 'Encerrado', IN_PLAY: 'Ao vivo', PAUSED: 'Ao vivo',
  POSTPONED: 'Adiado', SUSPENDED: 'Adiado', CANCELLED: 'Cancelado', SCHEDULED: 'Agendado', TIMED: 'Agendado',
};
const statusESPN = (ev) => {
  if (ev.statusNome === 'STATUS_POSTPONED') return 'Adiado';
  if (ev.statusNome === 'STATUS_CANCELED') return 'Cancelado';
  return { pre: 'Agendado', in: 'Ao vivo', post: 'Encerrado' }[ev.estado] ?? ev.statusNome;
};

// "90'+3'" -> 93
const minutoEmNumero = (s) => {
  const m = String(s).match(/(\d+)'?(?:\s*\+\s*(\d+))?/);
  return m ? Number(m[1]) + Number(m[2] ?? 0) : 0;
};

const resultados = jogos.map((j) => {
  const m = fd.find((x) => x.id === j.id);
  const nomesMandante = [j.mandante, ...(m?.nomesMandante ?? [])];
  const nomesVisitante = [j.visitante, ...(m?.nomesVisitante ?? [])];
  const achado = acharNaESPN(j, nomesMandante, nomesVisitante);
  const ev = achado?.ev;

  const situacao = m ? (statusFD[m.status] ?? m.status) : ev ? statusESPN(ev) : 'Sem dados';
  const golsCasa = m?.final?.home ?? (achado ? Number(achado.casa.placar) : null);
  const golsFora = m?.final?.away ?? (achado ? Number(achado.fora.placar) : null);
  const temPlacar = situacao === 'Encerrado' && golsCasa != null && golsFora != null;

  const r = {
    ...j,
    situacao,
    placar: temPlacar ? `${golsCasa} x ${golsFora}` : null,
    detalhesDaESPN: !!ev,
    fatos: {},
  };
  if (!temPlacar) return r;

  const f = r.fatos;
  const futebol = !['nfl', 'nba'].includes(j.codigo);
  f.placar = `${j.mandante} ${golsCasa} x ${golsFora} ${j.visitante}`;
  const margem = Math.abs(golsCasa - golsFora);

  if (futebol) {
    if (m?.intervalo?.home != null) f.intervalo = `${m.intervalo.home} x ${m.intervalo.away}`;
    if (m?.duracao === 'EXTRA_TIME') f.prorrogacao = 'decidido na prorrogação';
    if (m?.duracao === 'PENALTY_SHOOTOUT') f.prorrogacao = `decidido nos pênaltis (${m.penaltis?.home} x ${m.penaltis?.away})`;
    if (margem >= 3) f.goleada = true;

    if (ev) {
      const nomeDoTime = (id) => (id === achado.casa.id ? j.mandante : id === achado.fora.id ? j.visitante : '?');
      const gols = ev.lances.filter((l) => l.gol).sort((a, b) => minutoEmNumero(a.minuto) - minutoEmNumero(b.minuto));
      f.gols = gols.map((g) => `${g.minuto} ${g.jogador}${g.penalti ? ' (pênalti)' : ''}${g.contra ? ' (contra)' : ''} - ${nomeDoTime(g.timeId)}`);
      const expulsoes = ev.lances.filter((l) => l.vermelho);
      if (expulsoes.length) f.expulsoes = expulsoes.map((l) => `${l.minuto} ${l.jogador} - ${nomeDoTime(l.timeId)}`);

      // Virada, empate arrancado e gol decisivo no fim, refazendo o placar gol a gol.
      // Só confia na linha do tempo se a soma dos gols bater com o placar final.
      if (gols.length === golsCasa + golsFora) {
        let c = 0;
        let v = 0;
        let casaPerdeu = false;
        let foraPerdeu = false;
        let decisivo = null;
        for (const g of gols) {
          const antes = Math.sign(c - v);
          if (g.timeId === achado.casa.id) c++; else v++;
          if (c < v) casaPerdeu = true;
          if (v < c) foraPerdeu = true;
          // Gol que mudou o resultado (empate virou vitória ou derrota virou empate) a partir dos 85'
          if (minutoEmNumero(g.minuto) >= 85 && Math.sign(c - v) !== antes) decisivo = `${g.minuto} ${g.jogador} (${nomeDoTime(g.timeId)})`;
        }
        if (golsCasa > golsFora && casaPerdeu) f.virada = `${j.mandante} virou o jogo`;
        if (golsFora > golsCasa && foraPerdeu) f.virada = `${j.visitante} virou o jogo`;
        if (golsCasa === golsFora && (casaPerdeu || foraPerdeu)) f.empateArrancado = true;
        if (decisivo) f.golDecisivoNoFim = decisivo;
      }

      const est = (l) => l.estatisticas;
      if (est(achado.casa).possessionPct) f.posseDeBola = `${est(achado.casa).possessionPct}% x ${est(achado.fora).possessionPct}%`;
      if (est(achado.casa).shotsOnTarget) f.chutesNoGol = `${est(achado.casa).shotsOnTarget} x ${est(achado.fora).shotsOnTarget}`;
    } else if (m?.intervalo?.home != null) {
      // Sem a linha do tempo da ESPN, o intervalo ainda mostra se houve virada no segundo tempo
      const int = Math.sign(m.intervalo.home - m.intervalo.away);
      const fim = Math.sign(golsCasa - golsFora);
      if (int !== 0 && fim !== 0 && int !== fim) f.virada = `${fim > 0 ? j.mandante : j.visitante} virou no segundo tempo`;
    }
  } else if (ev) {
    // NFL e NBA: placar por quarto, prorrogação (mais de 4 parciais), destaques e manchete
    const pc = achado.casa.parciais;
    const pf = achado.fora.parciais;
    f.parciais = pc.map((p, i) => `${i < 4 ? `${i + 1}º` : 'prorrogação'}: ${p} x ${pf[i]}`).join('; ');
    if (pc.length > 4) f.prorrogacao = pc.length > 5 ? `${pc.length - 4} prorrogações` : 'decidido na prorrogação';
    f.margemFinal = `${margem} pontos`;
    const destaques = [achado.casa.destaque && `${j.mandante}: ${achado.casa.destaque}`, achado.fora.destaque && `${j.visitante}: ${achado.fora.destaque}`].filter(Boolean);
    if (destaques.length) f.destaques = destaques;
    if (ev.manchete) f.manchete = ev.manchete;
  }
  return r;
});

return [{ json: { data, jogos: resultados, falhas } }];

// Nó Code "Preparar avaliação" do workflow "Como foram os jogos" (modo: Run Once for All Items)
// Monta o pedido ao Gemini para dar a nota de DEPOIS do jogo, na mesma escala de 1 a 5 da pauta.
// O modelo recebe o contexto de antes do jogo (o briefing), mas NÃO recebe a nota prevista: assim ele
// avalia o que aconteceu sem se ancorar no número da manhã, e a comparação entre as duas notas vale alguma coisa.

const { data, jogos } = $('Montar resultados').first().json;

const lista = jogos
  .filter((j) => j.placar)
  .map((j) => ({
    id: j.id,
    campeonato: j.campeonato,
    jogo: `${j.mandante} x ${j.visitante}`,
    antesDoJogo: [j.porQueANota, j.briefing].filter(Boolean).join(' '),
    ...j.fatos,
  }));

const instrucoes = `Você é editor de pauta de um canal de esportes brasileiro e revisa os jogos de ontem.
Todos os jogos abaixo já terminaram. Para cada um, dê a nota que ele mereceu depois de jogado, de 1 a 5,
pensando no público brasileiro: o quanto valeu ter dado destaque a esse jogo.

A nota junta a importância do jogo ("antesDoJogo" diz o que estava em jogo) com o que aconteceu em campo:
5 = jogo para lembrar: virada, gol decisivo no fim, prorrogação ou overtime disputados, zebra grande, goleada de ou sobre time grande, jogo de muitos gols com placar apertado, ou jogo decisivo que cumpriu o que prometia.
4 = bom jogo: disputado, resultado que mexe na tabela ou atuação de destaque de uma estrela.
3 = jogo normal, resultado dentro do esperado.
2 = jogo morno: favorito venceu sem sustos ou empate sem graça.
1 = jogo muito fraco: 0 x 0 sem chances ou decidido cedo, sem nenhum interesse.

Na NBA e na NFL, jogo decidido por poucos pontos ou na prorrogação vale mais; vitória folgada (mais de 15 pontos na NBA, mais de 14 na NFL) vale menos.

Regras:
- Use só os fatos fornecidos (placar, gols, expulsões, virada, parciais, destaques, manchete). Não invente lances, jogadores nem estatísticas.
- Minuto de gol ou expulsão vai exatamente como nos fatos ("aos 89 minutos", "nos acréscimos" para 90'+): não converta para "X do segundo tempo".
- "comoFoi": 1 ou 2 frases curtas em português do Brasil, em tom de jornalista esportivo, com o fato principal do jogo (quem decidiu, virada, goleada, zebra). Cite jogadores só se aparecerem nos fatos.
- Avalie todos os jogos recebidos e devolva cada um com o mesmo id.`;

const body = {
  systemInstruction: { parts: [{ text: instrucoes }] },
  contents: [{ role: 'user', parts: [{ text: `Jogos da pauta de ${data}:\n${JSON.stringify(lista, null, 1)}` }] }],
  generationConfig: {
    temperature: 0.3,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        jogos: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              id: { type: 'STRING' },
              nota: { type: 'INTEGER' },
              comoFoi: { type: 'STRING' },
            },
            required: ['id', 'nota', 'comoFoi'],
          },
        },
      },
      required: ['jogos'],
    },
  },
};

return [{ json: { totalAvaliados: lista.length, body } }];

// Nó Code "Comparar notas" do workflow "Como foram os jogos" (modo: Run Once for All Items)
// Junta a nota de depois do jogo (Gemini) com a nota prevista na pauta e classifica cada jogo:
// "Na mosca" (mesma nota), "Perto" (1 ponto de diferença), "Superou" ou "Decepcionou" (2 pontos ou mais).
// Se o Gemini falhar, os placares seguem sem a nota de depois do jogo.

const { data, jogos, falhas } = $('Montar resultados').first().json;
const resposta = $('Gemini').first().json;

let avaliacoes = new Map();
let llmFalhou = false;
try {
  const texto = resposta.candidates[0].content.parts.map((p) => p.text ?? '').join('');
  avaliacoes = new Map(JSON.parse(texto).jogos.map((a) => [a.id, a]));
} catch (e) {
  llmFalhou = jogos.some((j) => j.placar);
}

const acerto = (diferenca) => {
  if (diferenca === 0) return 'Na mosca';
  if (Math.abs(diferenca) === 1) return 'Perto';
  return diferenca > 0 ? 'Superou' : 'Decepcionou';
};

const resultado = jogos.map((j) => {
  const a = avaliacoes.get(j.id);
  const notaJogo = a && Number.isInteger(a.nota) ? Math.min(5, Math.max(1, a.nota)) : null;
  const comparavel = j.placar && notaJogo != null && Number.isInteger(j.nota);
  return {
    ...j,
    notaJogo,
    comoFoi: a?.comoFoi ?? null,
    diferenca: comparavel ? notaJogo - j.nota : null,
    acerto: comparavel ? acerto(notaJogo - j.nota) : null,
  };
});

const avaliados = resultado.filter((j) => j.acerto);
const contar = (nome) => avaliados.filter((j) => j.acerto === nome).length;
const resumo = {
  total: resultado.length,
  avaliados: avaliados.length,
  naMosca: contar('Na mosca'),
  perto: contar('Perto'),
  superou: contar('Superou'),
  decepcionou: contar('Decepcionou'),
};

return [{ json: { data, jogos: resultado, resumo, llmFalhou, falhas } }];

// Nó Code "Separar resultados" do workflow "Como foram os jogos" (modo: Run Once for All Items)
// Um item por jogo, só com as colunas do resultado. O nó Airtable seguinte faz upsert pela coluna ID:
// como só vão estas colunas, a nota, o briefing e os outros campos gravados pela pauta ficam como estão.

const { jogos } = $('Comparar notas').first().json;

return jogos
  .filter((j) => j.situacao !== 'Sem dados')
  .map((j) => {
    const campos = { ID: j.id, Status: j.situacao };
    if (j.placar) campos['Placar'] = j.placar;
    if (j.notaJogo != null) campos['Nota do jogo'] = j.notaJogo;
    if (j.comoFoi) campos['Como foi'] = j.comoFoi;
    if (j.acerto) campos['Acerto da nota'] = j.acerto;
    return { json: campos };
  });

// Nó Code "Montar mensagem" do workflow "Como foram os jogos" (modo: Run Once for All Items)
// Mensagem do Telegram (HTML) com o resultado dos jogos da pauta de ontem e o acerto das notas.
// Os jogos vêm separados em: os que surpreenderam, os que decepcionaram e os que saíram como previsto.
// Sem jogo na pauta de ontem, não sai mensagem (nada para comparar).

const LIMITE = 3900;
const { data, jogos, resumo, llmFalhou, falhas } = $('Comparar notas').first().json;
if (!jogos.length) return [];

const html = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const selo = (nota) => (nota === 5 ? '🔥' : nota === 4 ? '⭐' : '▫️');
const dia = DateTime.fromISO(data).setLocale('pt-BR').toFormat('cccc, dd/MM');

const cabecalho = [`📊 <b>Como foram os jogos: ${html(dia)}</b>`];
if (resumo.avaliados) {
  cabecalho.push('Nota da pauta → nota depois do jogo (1 a 5)');
  const errou = resumo.superou + resumo.decepcionou;
  cabecalho.push(`🎯 ${resumo.naMosca} de ${resumo.avaliados} na mosca · ${resumo.perto} por 1 ponto · ${errou} ${errou === 1 ? 'errou' : 'erraram'} por 2 ou mais`);
}

const linhasDoJogo = (j) => {
  const linhas = [`${selo(j.nota)} <b>${html(j.mandante)} ${html(j.placar)} ${html(j.visitante)}</b> · ${html(j.campeonato)}`];
  if (j.notaJogo != null) linhas.push(`Nota ${j.nota} → ${j.notaJogo}`);
  else linhas.push(`Nota da pauta: ${j.nota}`);
  if (j.comoFoi) linhas.push(`<i>${html(j.comoFoi)}</i>`);
  return linhas.join('\n');
};

// Maior diferença primeiro dentro de cada grupo; empate pelo horário
const ordenar = (lista) => lista.sort((a, b) => Math.abs(b.diferenca ?? 0) - Math.abs(a.diferenca ?? 0) || String(a.horario).localeCompare(String(b.horario)));
const comPlacar = jogos.filter((j) => j.placar);
const grupos = [
  { titulo: '📈 <b>SURPREENDERAM</b>', jogos: ordenar(comPlacar.filter((j) => j.acerto === 'Superou')) },
  { titulo: '📉 <b>DECEPCIONARAM</b>', jogos: ordenar(comPlacar.filter((j) => j.acerto === 'Decepcionou')) },
  { titulo: '🎯 <b>COMO PREVISTO</b>', jogos: ordenar(comPlacar.filter((j) => ['Na mosca', 'Perto'].includes(j.acerto))) },
  { titulo: '📋 <b>RESULTADOS</b>', jogos: ordenar(comPlacar.filter((j) => !j.acerto)) },
];
const semResultado = jogos.filter((j) => !j.placar);

const avisos = [];
if (llmFalhou) avisos.push('⚠️ O Gemini não respondeu: placares sem a nota de depois do jogo.');
if (falhas.length) avisos.push(`⚠️ Fonte fora do ar (${html(falhas.map((f) => f.split(':')[0]).join(', '))}): alguns jogos podem estar sem placar ou sem detalhes.`);

const mensagens = [];
let atual = cabecalho.join('\n');
const fechar = () => { if (atual.trim()) mensagens.push(atual); atual = ''; };
const adicionar = (trecho) => {
  if (atual && (atual + '\n\n' + trecho).length > LIMITE) fechar();
  atual = atual ? `${atual}\n\n${trecho}` : trecho;
};

for (const g of grupos) {
  if (!g.jogos.length) continue;
  adicionar(g.titulo);
  for (const j of g.jogos) adicionar(linhasDoJogo(j));
}
if (semResultado.length) {
  adicionar(['⏸️ <b>SEM RESULTADO</b>', ...semResultado.map((j) => `${html(j.mandante)} x ${html(j.visitante)}: ${html(j.situacao.toLowerCase())}`)].join('\n'));
}
if (avisos.length) adicionar(avisos.join('\n'));
fechar();

return mensagens.map((texto) => ({ json: { texto } }));
